gpu_device_preflight_command:
PYTHONPATH=. python3 - "{run_root}" <<'PY'
import json, sys
from pathlib import Path

run_root = Path(sys.argv[1])
prelaunch = run_root / 'prelaunch'
prelaunch.mkdir(parents=True, exist_ok=True)
failures = []
try:
    import torch
except Exception as exc:
    failures.append(f'torch_import:{exc}')
    torch = None
device_name = None
if torch is not None and torch.cuda.is_available():
    device_name = torch.cuda.get_device_name(0)
else:
    failures.append('cuda_unavailable')
if device_name:
    lower = device_name.lower()
    if '1070' in lower:
        failures.append('audit_lane_gtx_1070_forbidden')
    if '4070' not in lower and 'laptop' not in lower:
        failures.append(f'unexpected_gpu:{device_name}')
receipt = {'schema': 'hrm_text_158_slice5_gpu_device_preflight/v1', 'device_name': device_name, 'pass': not failures, 'failures': failures}
out = prelaunch / 'gpu_device_preflight_receipt.json'
out.write_text(json.dumps(receipt, indent=2, sort_keys=True) + '\n', encoding='utf-8')
if failures:
    raise SystemExit(1)
print(json.dumps(receipt, indent=2))
PY

packet_self_validate_command:
PYTHONPATH=. python3 - <<'PY'
import ast
import hashlib
import json
import re
import subprocess
import tempfile
from pathlib import Path

failures = []
draft_path = Path('artifacts/consensus_prep/slice5_step2a_live_carrier_gpu_scale_smoke_launch_packet_v6i_draft.json')
replay_path = Path('artifacts/consensus_prep/slice5_step2a_live_carrier_gpu_scale_smoke_launch_packet_v6i_replay_commands.json')
draft = json.loads(draft_path.read_text(encoding='utf-8'))
replay = json.loads(replay_path.read_text(encoding='utf-8'))
V6I = 'v6i_extended_step_warmup_classifier'
RUN_ID = '2189e72029'
MAX_STEPS = 8
V6I_SCRIPT = 'scripts/hrm_text_158_slice5_v6i_postrun_acceptance_validate.py'
V6H_SCRIPT = 'scripts/hrm_text_158_slice5_v6h_postrun_acceptance_validate.py'
REQUIRED_PIN_PATHS = [
    'calm/hrm_text_158/native_full_stack/bounded_delta_learner.py',
    'calm/hrm_text_158/native_full_stack/event_coded_vote_update_adapter.py',
    'calm/hrm_text_158/native_full_stack/phase_stack_ring_sampler.py',
    'calm/hrm_text_158/native_full_stack/sparse_cap_gpu_seam_adapter.py',
    'scripts/hrm_text_158_bounded_delta_acquisition_probe.py',
    'scripts/hrm_text_158_slice5_cap_selection_path_evidence.py',
    'scripts/hrm_text_158_slice5_launch_arm_barrier.py',
    'scripts/hrm_text_158_slice5_launch_injected_dispatch_witness.py',
    'scripts/hrm_text_158_slice5_live_carrier_scale_smoke_receipt.py',
    'scripts/hrm_text_158_slice5_postrun_receipt_replay.py',
    V6H_SCRIPT,
    V6I_SCRIPT,
]

if draft.get('run_id') != RUN_ID:
    failures.append('draft_run_id_mismatch')
if not str(draft.get('run_root', '')).rstrip('/').endswith(RUN_ID):
    failures.append('draft_run_root_suffix_mismatch')
if replay.get('run_id') != RUN_ID:
    failures.append('replay_run_id_mismatch')
if not str(replay.get('run_root', '')).rstrip('/').endswith(RUN_ID):
    failures.append('replay_run_root_suffix_mismatch')
if draft.get('source_base_head') != '3ee73541bb125071b48e46eec5f8d58e833f7e82':
    failures.append('draft_source_base_head_mismatch')
if draft.get('validator_packet_head') != 'fde2051039e80b63aed723e579c8e78419fa17b2':
    failures.append('validator_packet_head_mismatch')
if draft.get('classifier_only') is not True:
    failures.append('classifier_only_not_true')
if draft.get('scale_smoke', {}).get('max_steps_hard') != MAX_STEPS:
    failures.append('max_steps_hard_not_8')

active_blob = json.dumps({
    'terminal_classification_matrix': draft.get('decision_thresholds', {}).get('terminal_classification_matrix', {}),
    'decision_contract': draft.get('decision_contract', {}),
    'launch_sequence': replay.get('launch_sequence', []),
    'binds_main_packet': replay.get('binds_main_packet'),
    'packet_revision': draft.get('packet_revision'),
    'run_id': draft.get('run_id'),
    'run_root': draft.get('run_root'),
}, sort_keys=True)
for pat in (
    'v6e_re_m4', 'v6e_draft', 'v6e_replay', '2189e72025',
    'v6f_re_m4', 'v6f_draft', 'v6f_replay', '2189e72026',
    'v6g_re_m4', 'v6g_draft', 'v6g_replay', '2189e72027',
    'v6h_re_m4', 'v6h_draft', 'v6h_replay', '2189e72028',
):
    if pat in active_blob:
        failures.append(f'stale_active_reference:{pat}')

SENTINEL = 'LAUNCH_INJECTED_BY_CLAUDE'
for surface, blob in (('draft', draft), ('replay', replay)):
    if str(blob.get('dispatch_msg_id')) != SENTINEL:
        failures.append(f'{surface}_dispatch_msg_id_not_sentinel')
    if str(blob.get('dispatch_msg_id_authority')) != 'launch_injected':
        failures.append(f'{surface}_dispatch_msg_id_authority_not_launch_injected')

witness_cmd = str(replay.get('launch_injected_dispatch_witness_command') or '')
if '--dispatch-msg-id' in witness_cmd:
    failures.append('witness_command_must_not_take_dispatch_msg_id')

seq = replay.get('launch_sequence', [])
if 'launch_injected_dispatch_witness_command' not in seq:
    failures.append('missing_launch_injected_dispatch_witness_command')
else:
    inj = seq.index('launch_injected_dispatch_witness_command')
    base = seq.index('baseline_gpu_command')
    if inj >= base:
        failures.append('injected_dispatch_witness_not_before_gpu_arms')
if 'v6i_postrun_acceptance_validate_command' not in seq:
    failures.append('missing_v6i_postrun_acceptance_validate_command')
else:
    if seq.index('v6i_postrun_acceptance_validate_command') <= seq.index('live_carrier_scale_smoke_receipt_command'):
        failures.append('v6i_postrun_acceptance_validate_not_after_live_carrier_receipt')

for key in ('baseline_gpu_command', 'instrumented_gpu_command'):
    text = str(replay.get(key) or '')
    if 'HRM_TEXT_158_RUN_GPU_GLOBAL_RATE_CAP=1' not in text:
        failures.append(f'missing_gpu_global_rate_cap_env_in_{key}')
    if 'HRM_TEXT_158_RUN_GPU_Q_ACC_APPLY=1' not in text:
        failures.append(f'missing_gpu_q_acc_apply_env_in_{key}')
    if f'--max-steps-hard {MAX_STEPS}' not in text:
        failures.append(f'max_steps_hard_not_8_in_{key}')

for key in ('shared_probe_argv', 'baseline_gpu_command', 'instrumented_gpu_command'):
    text = str(replay.get(key) or '')
    if '--phase-timeout-seconds 900' not in text:
        failures.append(f'missing_phase_timeout_900_in_{key}')
    if '--phase-timeout-seconds 300' in text:
        failures.append(f'stale_phase_timeout_300_in_{key}')

on_disk_pins = {
    rel: hashlib.sha256(Path(rel).read_bytes()).hexdigest()
    for rel in REQUIRED_PIN_PATHS
}
draft_pins = draft.get('source_pins_at_launch') or {}

for rel in REQUIRED_PIN_PATHS:
    if rel not in draft_pins:
        failures.append(f'source_pins_missing_launch_critical:{rel}')
    elif draft_pins.get(rel) != on_disk_pins[rel]:
        failures.append(f'source_pins_on_disk_sha_mismatch:{rel}')

for witness_key, dict_name in (
    ('file_content_pin_witness_command', 'PINS'),
    ('head_pin_witness_command', 'SOURCE_PINS'),
):
    cmd = str(replay.get(witness_key) or '')
    match = re.search(rf'{dict_name} = (\{{.*?\}})\n', cmd, re.S)
    if not match:
        failures.append(f'{witness_key}_missing_pin_dict')
        continue
    witness_pins = ast.literal_eval(match.group(1))
    if witness_pins != draft_pins:
        failures.append(f'{witness_key}_pins_mismatch_vs_source_pins_at_launch')
    for rel in REQUIRED_PIN_PATHS:
        if rel not in witness_pins:
            failures.append(f'{witness_key}_missing_launch_critical:{rel}')
        elif witness_pins.get(rel) != on_disk_pins[rel]:
            failures.append(f'{witness_key}_on_disk_sha_mismatch:{rel}')

if V6I_SCRIPT not in draft_pins:
    failures.append('source_pins_missing_v6i_validator')
if V6H_SCRIPT not in draft_pins:
    failures.append('source_pins_missing_v6h_validator_dependency')

with tempfile.TemporaryDirectory() as tmp:
    run_root = Path(tmp) / 'run'
    run_root.mkdir()
    for key in (
        'run_root_free_assert_command',
        'file_content_pin_witness_command',
        'head_pin_witness_command',
        'argv_witness_command',
    ):
        cmd = str(replay.get(key) or '').replace('{run_root}', str(run_root))
        if not cmd:
            failures.append(f'missing_{key}')
            continue
        proc = subprocess.run(['bash', '-lc', cmd], capture_output=True, text=True)
        if proc.returncode != 0:
            failures.append(f'prelaunch_dry_run_failed:{key}:exit_{proc.returncode}')

receipt = {
    'schema': 'hrm_text_158_packet_self_validate/v6i',
    'packet_revision': V6I,
    'pass': not failures,
    'failures': failures,
}
print(json.dumps(receipt, indent=2, sort_keys=True))
if failures:
    raise SystemExit(1)
PY
